from collections import Counter,deque
import numpy as np
def solve(G,inpt=False):
    H,W=len(G),len(G[0])
    bgc=None
    # dominant background color(s): colors of large components
    lab=-np.ones((H,W),int); comps={}
    cid=0
    for i in range(H):
        for j in range(W):
            if lab[i][j]!=-1: continue
            col=G[i][j]; q=deque([(i,j)]); size=0; lab[i][j]=cid
            while q:
                y,x=q.popleft(); size+=1
                for di,dj in[(1,0),(-1,0),(0,1),(0,-1)]:
                    a,b=y+di,x+dj
                    if 0<=a<H and 0<=b<W and lab[a][b]==-1 and G[a][b]==col:
                        lab[a][b]=cid; q.append((a,b))
            comps[cid]=(col,size,(y+x))
            cid+=1
    # dominant backgrounds = biggest components
    sizes=sorted((v[1] for v in comps.values()),reverse=True)
    thresh=sizes[1]*2  # smaller than second-biggest
    bigs=[k for k,v in comps.items() if v[1]>=thresh]
    res=np.array(G)
    for i in range(H):
        for j in range(W):
            if lab[i][j] not in bigs:
                nb=[G[i+di][j+dj] for di,dj in[(1,0),(-1,0),(0,1),(0,-1)] if 0<=i+di<H and 0<=j+dj<W and lab[i+di][j+dj] in bigs]
                c=Counter(nb).most_common()
                res[i][j]=c[0][0]
    return [[int(x) for x in r] for r in res]

